import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DwhuN-9m.js";var i=JSON.parse(`{"title":"Installing Dependencies","description":"","frontmatter":{"id":"guide.installing-dependencies","title":"Installing Dependencies","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/installing-dependencies.md","filePath":"guides/installing-dependencies.md"}`),a={name:`guides/installing-dependencies.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="installing-dependencies" tabindex="-1">Installing Dependencies <a class="header-anchor" href="#installing-dependencies" aria-label="Permalink to “Installing Dependencies”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p><code>bento install</code> installs a project&#39;s <code>dependencies</code> and <code>devDependencies</code> by running the project&#39;s declared pnpm toolchain in the project root. Bento does not implement a second package manager or lockfile writer: pnpm reads and writes <code>pnpm-lock.yaml</code>, including the document that pins pnpm&#39;s own version, and applies <code>pnpm-workspace.yaml</code>.</p><p>Installing is a separate step from running. <code>bento run</code> never installs packages, resolves new versions, or downloads modules.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><ol><li><p>Declare pnpm in <code>package.json</code>, if the project does not already:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;devEngines&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: { </span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">&quot;packageManager&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: { </span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">&quot;name&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;pnpm&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">, </span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">&quot;version&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">: </span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;12&quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;"> } }</span></span></code></pre></div></li><li><p>Make sure <code>pnpm</code> is on your <code>PATH</code>. Bento runs the <code>pnpm</code> it finds there, and pnpm switches to the version the project pins, which may need registry access the first time.</p></li><li><p>Run <code>bento install</code> anywhere inside the project. Bento finds the nearest <code>package.json</code>, runs <code>pnpm install</code> in that directory, shows pnpm&#39;s output, and exits with pnpm&#39;s exit status when the installation fails.</p></li><li><p>Use <code>bento install --frozen-lockfile</code> to reproduce exactly the locked dependency graph. If <code>package.json</code> and <code>pnpm-lock.yaml</code> disagree, the installation fails and <code>pnpm-lock.yaml</code> is left byte-for-byte unchanged.</p></li></ol><p>Without <code>--frozen-lockfile</code>, pnpm&#39;s normal behavior applies: it updates <code>pnpm-lock.yaml</code> to match <code>package.json</code>. That includes pnpm&#39;s own rule that a lockfile is frozen by default when the <code>CI</code> environment variable is set.</p><p>Bento stops before running anything when <code>devEngines.packageManager</code> is missing or names another package manager, and tells you what to declare. When <code>pnpm</code> is not on <code>PATH</code>, it reports pnpm as a missing prerequisite.</p><h3 id="development-dependencies" tabindex="-1">Development dependencies <a class="header-anchor" href="#development-dependencies" aria-label="Permalink to “Development dependencies”">​</a></h3><p><code>devDependencies</code> are always installed, even when <code>NODE_ENV=production</code> is set in your environment: Bento runs pnpm with <code>--production=false</code>. Project tasks rely on them for formatting, linting, type checking, and migrations.</p><h3 id="build-scripts" tabindex="-1">Build scripts <a class="header-anchor" href="#build-scripts" aria-label="Permalink to “Build scripts”">​</a></h3><p>Bento never approves dependency build scripts. It passes no flag or environment variable that allows them, so pnpm applies the project&#39;s own policy, the <code>allowBuilds</code> entries in <code>pnpm-workspace.yaml</code>. A dependency whose build script is not approved does not run it, and pnpm 12 fails the installation and names the package. If you trust that package, approve it in <code>pnpm-workspace.yaml</code>, for example with <code>pnpm approve-builds</code>, and install again.</p><h3 id="running-without-the-installer" tabindex="-1">Running without the installer <a class="header-anchor" href="#running-without-the-installer" aria-label="Permalink to “Running without the installer”">​</a></h3><p>Once dependencies are installed, <code>bento run</code> and an embedding Rust host execute the project without pnpm, Node, Bun, or Deno on the <code>PATH</code>. A dependency that is not installed fails at the import that needs it; run <code>bento install</code> and try again.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><p>The guest-book fixture declares <code>&quot;devEngines&quot;: { &quot;packageManager&quot;: { &quot;name&quot;: &quot;pnpm&quot;, &quot;version&quot;: &quot;12&quot;, &quot;onFail&quot;: &quot;download&quot; } }</code> and its <code>pnpm-lock.yaml</code> pins pnpm 12.11.2.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">cd</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> fixtures/remix-guest-book</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --frozen-lockfile</span></span></code></pre></div><p>pnpm switches to 12.11.2 and installs <code>remix@3.0.0</code> with the formatter, linter, and type checker from <code>devDependencies</code>, exactly as locked. If someone had added a dependency to <code>package.json</code> without updating the lockfile, the same command would fail with pnpm&#39;s outdated-lockfile error and leave <code>pnpm-lock.yaml</code> untouched.</p><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>pnpm is the only supported package manager, declared as a single <code>devEngines.packageManager</code> object.</li><li>Installing may need Node, pnpm, and registry access. Only running the installed project is free of them.</li><li><code>bento install</code> passes pnpm the environment it was started with. It does not load <code>.env</code> files, and pnpm settings from <code>.npmrc</code> files or <code>pnpm_config_*</code> variables still apply.</li></ul>`,20)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};